+void NetworkModel::updateVpnDevice(NetworkModelItem *item)
+{
+    QString vpnDevicePath;
+    NetworkManager::ActiveConnection::Ptr activeConnection = NetworkManager::findActiveConnection(item->activeConnectionPath());
+
+    // NetworkManager doesn't say which interface a VPN created, so look for the one that got the VPN's addresses
+    if (activeConnection && item->connectionState() == NetworkManager::ActiveConnection::Activated) {
+        const NetworkManager::IpAddresses vpnAddresses = activeConnection->ipV4Config().addresses() + activeConnection->ipV6Config().addresses();
+        const NetworkManager::Device::List devices = NetworkManager::networkInterfaces();
+        for (const NetworkManager::Device::Ptr &device : devices) {
+            if (activeConnection->devices().contains(device->uni())) {
+                continue;
+            }
+            const NetworkManager::IpAddresses deviceAddresses = device->ipV4Config().addresses() + device->ipV6Config().addresses();
+            const bool hasVpnAddress = std::any_of(vpnAddresses.cbegin(), vpnAddresses.cend(), [&deviceAddresses](const NetworkManager::IpAddress &vpnAddress) {
+                return std::any_of(deviceAddresses.cbegin(), deviceAddresses.cend(), [&vpnAddress](const NetworkManager::IpAddress &deviceAddress) {
+                    return deviceAddress.ip() == vpnAddress.ip();
+                });
+            });
+            if (hasVpnAddress) {
+                vpnDevicePath = device->uni();
+                break;
+            }
+        }
+    }
+
+    item->setVpnDevicePath(vpnDevicePath);
+}
